"""hlife-patch.py <tree>: scratch per-CTA lifetime stamps in hybrid_combine.cuh (Attention domains only)."""
import sys
p = sys.argv[1] + "/afdep/third_party/deepep_v2/deep_ep/include/deep_ep/impls/hybrid_combine.cuh"
s = open(p).read()
old = "    // Utils\n    const auto sm_idx = static_cast<int>(blockIdx.x);\n"
assert s.count(old) == 1
s = s.replace(old, "    unsigned long long afd_t0; asm volatile(\"mov.u64 %0, %%globaltimer;\" : \"=l\"(afd_t0));  // SCRATCH\n" + old)
old = "    // No barrier at epilogue\n}"
assert s.count(old) == 1
s = s.replace(old, """    // No barrier at epilogue
    // SCRATCH: CTA lifetime (last warp) on Attention domains.
    __syncthreads();
    if (threadIdx.x == 0 and kAfdFfnScaleoutRanks > 0 and scaleout_rank_idx >= kAfdFfnScaleoutRanks and scaleup_rank_idx == 0) {
        unsigned long long t1; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t1));
        printf("AFDLIFE cta %d start %llu end %llu\\n", (int)blockIdx.x, afd_t0, t1);
    }
}""")
open(p, "w").write(s)
print("patched", p)

