"""p1-faults.py <tree> <F1|F2|F3|F5|F6>: apply one scratch fault to a copied tree (never shipped)."""
import sys
from pathlib import Path

tree, fault = Path(sys.argv[1]), sys.argv[2]
impls = tree / "afdep/third_party/deepep_v2/deep_ep/include/deep_ep/impls"


def patch(name, old, new):
    path = impls / name
    text = path.read_text()
    assert text.count(old) == 1, (name, old[:60])
    path.write_text(text.replace(old, new))


SPIN = """// FAULT INJECTION (scratch only)
__device__ __forceinline__ void afd_fault_spin(const unsigned long long ns) {
    unsigned long long t0, t;
    asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t0));
    do { asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t)); } while (t - t0 < ns);
}

constexpr int kAfdepDispatchPhase = 0;"""
patch("afdep_roles.cuh", "constexpr int kAfdepDispatchPhase = 0;", SPIN)
LATE_CTA = """                                                       const int sm_idx, const int thread_idx) {
    // FAULT: the last sender CTA releases its arrival 50 us late.
    if (blockIdx.x == gridDim.x - 1 and threadIdx.x == 0)
        afd_fault_spin(50000);
    // Every CTA's TMA stores complete before the arrival release."""
if fault in ("F1", "F2"):
    patch("afdep_roles.cuh", """                                                       const int sm_idx, const int thread_idx) {
    // Every CTA's TMA stores complete before the arrival release.""", LATE_CTA)
if fault == "F2":
    # Receiver counts one arrival per sender per round: must release early and read stale rows.
    patch("afdep_roles.cuh", "* kNumSenderCtas;", "* 1;")
if fault == "F3":
    # Receiver expects one arrival more than senders release: must time out.
    patch("afdep_roles.cuh", "* kNumSenderCtas;", "* (kNumSenderCtas + 1);")
if fault == "F5":
    # The FFN receive publishes its expert prefix sum 100 us late.
    patch("dispatch.cuh", """            } else if (warp_idx == 1) {
                // Exclusive prefix sum for later expanding""", """            } else if (warp_idx == 1) {
                // FAULT: late expert prefix sum.
                if (lane_idx == 0)
                    afd_fault_spin(100000);
                __syncwarp();
                // Exclusive prefix sum for later expanding""")
if fault == "F6":
    # The receiver's waiting thread starts its wait 100 us late.
    patch("afdep_roles.cuh", """    if (sm_idx != 0 or thread_idx != 0)
        return;
""", """    if (sm_idx != 0 or thread_idx != 0)
        return;
    afd_fault_spin(100000);  // FAULT: late receiver
""")
print("applied", fault)
